<?php require_once __DIR__ . '/../app/bootstrap.php'; use App\Middleware\AuthMiddleware; use App\Security\Csrf; use App\Services\Database; AuthMiddleware::requireRole('admin'); if($_SERVER['REQUEST_METHOD']==='POST' && Csrf::verify($_POST['_csrf']??null)){Database::connection()->prepare('UPDATE users SET role=? WHERE id=?')->execute([$_POST['role'],(int)$_POST['id']]);} $rows=Database::connection()->query('SELECT id,name,email,role FROM users ORDER BY created_at DESC')->fetchAll(); ?>
<!doctype html><html><head><script src="https://cdn.tailwindcss.com"></script></head><body class="bg-[#F5E9DA] p-6"><div class="bg-white rounded shadow p-4"><h1 class="text-2xl mb-3">Users</h1><?php foreach($rows as $u):?><form method="POST" class="flex gap-2 border-b py-2"><input type="hidden" name="_csrf" value="<?=htmlspecialchars(Csrf::token())?>"><input type="hidden" name="id" value="<?=$u['id']?>"><span class="flex-1"><?=htmlspecialchars($u['name'])?> (<?=htmlspecialchars($u['email'])?>)</span><select name="role" class="border"><option <?= $u['role']==='client'?'selected':''?>>client</option><option <?= $u['role']==='trainer'?'selected':''?>>trainer</option><option <?= $u['role']==='admin'?'selected':''?>>admin</option></select><button class="bg-[#C9A227] text-white px-3 rounded">Save</button></form><?php endforeach;?></div></body></html>
